import glob,gzip,csv,re
for p in sorted(glob.glob('studies/data/raw/*series*')):
 print('\n',p)
 rows=[next(csv.reader([l],delimiter='\t')) for l in gzip.open(p,'rt') if l.startswith('!Sample')]
 for r in rows:
  if r[0] not in ['!Sample_title']:
   hits=[(i,v) for i,v in enumerate(r[1:]) if re.search(r'\brep(?:licate)?\s*[0-9]|replicate:',v,re.I)]
   if hits: print(r[0],hits[:20])
